use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AuditEvent {
    pub index: usize,
    pub thread_id: usize,
    pub kind: String,
    pub node: String,
}

#[derive(Debug, Default)]
pub struct AuditTimeline {
    events: Vec<AuditEvent>,
    next_index: usize,
    thread_events: HashMap<usize, Vec<AuditEvent>>,
}

impl AuditTimeline {
    pub fn new() -> Self {
        Self {
            events: Vec::new(),
            next_index: 1,
            thread_events: HashMap::new(),
        }
    }

    pub fn record(&mut self, thread_id: usize, kind: &str, node: &str) {
        let event = AuditEvent {
            index: self.next_index,
            thread_id,
            kind: kind.to_string(),
            node: node.to_string(),
        };

        self.events.push(event.clone());
        self.thread_events
            .entry(thread_id)
            .or_insert_with(Vec::new)
            .push(event);
        self.next_index += 1;
    }

    pub fn events_for_thread(&self, thread_id: usize) -> Vec<AuditEvent> {
        self.thread_events.get(&thread_id).cloned().unwrap_or_default()
    }
}
