use std::collections::{HashMap, VecDeque};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PreloadPlanner {
    nodes: HashMap<String, Vec<String>>,
}

impl PreloadPlanner {
    pub fn new() -> Self {
        PreloadPlanner {
            nodes: HashMap::new(),
        }
    }

    pub fn connect(&mut self, from: &str, to: &str) {
        self.nodes.entry(from.to_string()).or_default().push(to.to_string());
        self.nodes.entry(to.to_string()).or_default();
    }

    pub fn preload_from(&self, start_node: &str, depth: usize) -> Vec<String> {
        if depth == 0 {
            return vec![];
        }

        let mut visited = HashMap::new();
        let mut queue = VecDeque::new();
        let mut result = Vec::new();

        // Start with the initial node
        queue.push_back(start_node.to_string());
        visited.insert(start_node.to_string(), true);

        for _ in 0..depth {
            let level_size = queue.len();
            for _ in 0..level_size {
                if let Some(current) = queue.pop_front() {
                    // Add neighbors to result and queue
                    if let Some(neighbors) = self.nodes.get(&current) {
                        for neighbor in neighbors {
                            if !visited.contains_key(neighbor) {
                                visited.insert(neighbor.clone(), true);
                                queue.push_back(neighbor.clone());
                                result.push(neighbor.clone());
                            }
                        }
                    }
                }
            }
        }

        result
    }
}
